	virtual void DoEvent(EventNumber eventNumber,								TEventHandler* source,								TEvent* event);		// If the hit is mCheckBoxHit then toggle the checkbox.	// The following three functions are non-virtual helper functions	// for GetValue and SetValue.  If you need to override any one of these,	// you must override GetValue or SetValue instead.		bool IsOn() const;		// Is the checkbox currently checked.	inline SInt16 GetState() const { return static_cast<SInt16> (GetValue()); }		// Returns the state of the checkbox as a short.  Same as calling GetValue.			void SetState(SInt16 state, bool redraw);		// Sets the state of the checkbox to state and if redraw is true redraws it.		// Same as calling SetValue.	virtual void Toggle(bool redraw);		// Toggles the state of the checkbox redraw it if redraw is true.	virtual void ToggleIf(bool matchState, bool redraw);		// Toggles the state of the checkbox if matchState is true redrawing if redraw is        // true.		virtual CControl_AC* DoMakeControl(WindowRef theWindow, 										const CRect_AC& boundsRect, 										bool isVisible, bool isEnabled, 										const CStr255_AC& itsTitle);#if qMSWindows	virtual void CreateWindowsWindow();	virtual long HandleWindowsEvent(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);#endif	ResNumber GetStrListID() const	{ return fStrListID; }	short GetIndex() const		{ return fIndex; }	void SetStrListID(ResNumber id)	{ fStrListID = id; }	void SetIndex(short index)	{ fIndex = index; }	void SetLabel(ResNumber id, short index)	{ fStrListID = id; fIndex = index; }#if qBackwardCompatiblepublic:#elseprotected:#endif	ResNumber	fStrListID;		// The ID of the 'STR#' resource containing the label of								// the check box in the position specified by the fIndex								// field.	short		fIndex;			// The index specifying the position occupied by the check								// box's label in the 'STR#' resource specified by the								// fStrListID field.	short		fInitialState;	// The control's initial state.								// This value is only set by the constructor or 								// by ReadFrom via the view resource.};EXPORT_MA  void InitUCheckbox();#endif // __UCHECKBOX__/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/17/96	InitUCheckbox		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/